import { errorMessage } from "./error";

interface BadgePorts {
  write: (count: number) => Promise<void>;
  current: () => boolean;
  /** Content-free diagnostic, cleared only by an acknowledged update. */
  status: (error: string | null) => void;
}

/** One latest-value writer; bounded backoff and admission survive native stalls. */
export function createBadgeSync(ports: BadgePorts) {
  let active = true;
  let busy = false;
  let desired: number | null = null;
  let revision = 0;
  let applied = -1;
  let failures = 0;
  let pending = 0;
  let retryTimer: ReturnType<typeof setTimeout> | undefined;
  let deadline: ReturnType<typeof setTimeout> | undefined;
  const current = () => active && ports.current();
  const cancelRetry = () => {
    clearTimeout(retryTimer);
    retryTimer = undefined;
  };
  const schedule = () => {
    if (!current()) return;
    cancelRetry();
    retryTimer = setTimeout(
      () => {
        retryTimer = undefined;
        void flush();
      },
      Math.min(30_000, 1000 * 2 ** Math.min(5, failures - 1)),
    );
  };
  const flush = async () => {
    if (!current() || busy || desired === null || applied === revision) return;
    // A webview deadline cannot cancel native work. Never admit unlimited hung writes.
    if (pending >= 4) {
      schedule();
      return;
    }
    busy = true;
    const attempt = revision;
    const count = desired;
    pending++;
    try {
      await new Promise<void>((resolve, reject) => {
        deadline = setTimeout(
          () => reject(new Error("Badge update timed out")),
          5000,
        );
        try {
          Promise.resolve(ports.write(count)).then(
            () => {
              pending--;
              resolve();
            },
            (error: unknown) => {
              pending--;
              reject(error);
            },
          );
        } catch (error) {
          pending--;
          reject(error);
        }
      });
      if (!current()) return;
      applied = attempt;
      failures = 0;
      ports.status(null);
    } catch (error) {
      if (!current()) return;
      failures++;
      ports.status(errorMessage(error));
    } finally {
      clearTimeout(deadline);
      deadline = undefined;
      busy = false;
      if (current() && attempt !== revision) void flush();
      else if (current() && applied !== revision) schedule();
    }
  };
  return {
    update(count: number, force = false) {
      if (!current()) return;
      if (desired !== count || force) {
        desired = count;
        revision++;
      }
      if (applied === revision) return;
      cancelRetry();
      void flush();
    },
    stop() {
      active = false;
      cancelRetry();
      clearTimeout(deadline);
    },
  };
}
import { create } from "zustand";
import { chat } from "@/lib/api/chat";
import { createBadgeSync } from "@/lib/badgeSync";
import { captureRuntimeOwner } from "./ownership";
import { useChat } from "./chat";

export function unreadTotal(state: {
  unread: Record<string, number>;
  pendingUnknownUnread: Record<string, number>;
}): number {
  return [
    ...Object.values(state.unread),
    ...Object.values(state.pendingUnknownUnread),
  ].reduce(
    (sum, count) =>
      sum + (Number.isSafeInteger(count) && count > 0 ? count : 0),
    0,
  );
}

export const useUnreadBadge = create<{
  error: string | null;
  retry: () => void;
}>(() => ({ error: null, retry: () => {} }));

/** Bind badge work once to the exact desktop/account/runtime lifetime. */
export function startUnreadBadge(owner: string): () => void {
  const lease = captureRuntimeOwner();
  const account = useChat.getState().myAccountId;
  const current = () =>
    lease.owner === owner &&
    lease.current() &&
    useChat.getState().myAccountId === account;
  const sync = createBadgeSync({
    current,
    write: (count) => chat.setBadge(Math.min(0xffffffff, count), owner),
    status: (error) => {
      if (current()) useUnreadBadge.setState({ error });
    },
  });
  const retry = () => {
    if (current()) sync.update(unreadTotal(useChat.getState()), true);
  };
  useUnreadBadge.setState({ error: null, retry });
  const unsubscribe = useChat.subscribe((state, previous) => {
    if (
      state.unread !== previous.unread ||
      state.pendingUnknownUnread !== previous.pendingUnknownUnread
    )
      sync.update(unreadTotal(state));
  });
  let frame = 0;
  const onFocus = () => {
    if (!current()) return;
    useChat.getState().markLegacyActiveRead();
    cancelAnimationFrame(frame);
    frame = requestAnimationFrame(() => {
      if (!current()) return;
      useChat.getState().markLegacyActiveRead();
      retry();
    });
    retry();
  };
  window.addEventListener("focus", onFocus);
  document.addEventListener("visibilitychange", onFocus);
  retry();
  return () => {
    unsubscribe();
    sync.stop();
    cancelAnimationFrame(frame);
    window.removeEventListener("focus", onFocus);
    document.removeEventListener("visibilitychange", onFocus);
    if (useUnreadBadge.getState().retry === retry)
      useUnreadBadge.setState({ error: null, retry: () => {} });
  };
}
