import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { inspectPng } from './scripts/evals/png-evidence.mjs';
async function visit(path) {
 for (const entry of await readdir(path, { withFileTypes: true })) {
  const child = join(path, entry.name);
  if (entry.isDirectory()) await visit(child);
  else if (/^portable-browser-screenshot-.*\.png$/.test(entry.name)) console.log(child, inspectPng(await readFile(child)));
 }
}
await visit('tmp/post-merge-verify/observer-evidence-webkit');
